export const nutrientKeys=['kcal','protein','carbs','fat','cost'];
export const zero=()=>Object.fromEntries(nutrientKeys.map(k=>[k,0]));
export function totals(entries){return entries.reduce((a,e)=>{for(const k of nutrientKeys)a[k]+=e.nutrition?.[k]||0;return a;},zero());}
export function ingredientNutrition(i,grams,price){const n=zero();for(const k of ['kcal','protein','carbs','fat'])n[k]=i[k]*grams/100;n.cost=grams/(price?.pack||i.pack*(i.gramsPerUnit||1))*(price?.price??i.price);return n;}
export function ensureFoodState(s,recipeNutrition,recipeName){s.customIngredients||={};s.customRecipes||=[];s.hiddenIngredients||=[];s.foodFavorites||=[];if(s.foodSchema===1){s.foodEntries||=[];return;}
 s.foodEntries=s.foodLogs.map(f=>({id:'legacy-'+f.day,day:f.day,time:'12:00',name:'Previous daily total',kind:'quick',amount:1,nutrition:{...zero(),kcal:f.kcal,protein:f.protein}}));
 for(const m of s.mealLogs)if(!s.foodLogs.some(f=>f.day===m.day))s.foodEntries.push({id:m.id,day:m.day,time:m.time||'12:00',name:recipeName(m.recipe),kind:'recipe',ref:m.recipe,amount:m.servings,nutrition:{...zero(),...(m.nutrition||recipeNutrition(m.recipe,m.servings))}});
 s.foodSchema=1;
}
export function syncDay(s,day){const n=totals(s.foodEntries.filter(e=>e.day===day)),old=s.foodLogs.find(f=>f.day===day);s.foodLogs=s.foodLogs.filter(f=>f.day!==day);s.foodLogs.push({day,kcal:n.kcal,protein:n.protein,complete:old?.complete||false});}
export function validateFoodExtension(s){if(!s||typeof s!=='object')return;const obj=x=>x&&typeof x==='object'&&!Array.isArray(x),num=(n,max=100000)=>Number.isFinite(n)&&n>=0&&n<=max,validId=id=>typeof id==='string'&&/^[a-zA-Z0-9_-]{1,100}$/.test(id)&&!['__proto__','constructor','prototype'].includes(id);
 if(s.customIngredients!==undefined){if(!obj(s.customIngredients)||Object.keys(s.customIngredients).length>5000)throw Error('Invalid ingredients');for(const [id,i]of Object.entries(s.customIngredients)){if(!validId(id)||!obj(i)||typeof i.name!=='string'||!i.name.trim()||i.name.length>150||!['g','ml','each'].includes(i.unit)||!num(i.pack)||i.pack<=0||!num(i.gramsPerUnit)||i.gramsPerUnit<=0||!num(i.price)||!['kcal','protein','carbs','fat'].every(k=>num(i[k],k==='kcal'?1000:100))||!Array.isArray(i.allergens)||!i.allergens.every(a=>typeof a==='string')||typeof i.vegetarian!=='boolean')throw Error('Invalid ingredient');}}
 for(const i of Object.values(s.customIngredients||{}))if(i.nutritionSource&&(!/^https:\/\//.test(i.nutritionSource.url)||typeof i.nutritionSource.description!=='string'))throw Error('Invalid ingredient source');
 if(s.customRecipes!==undefined){if(!Array.isArray(s.customRecipes)||s.customRecipes.length>5000)throw Error('Invalid recipes');const ids=new Set;for(const r of s.customRecipes){if(!obj(r)||!validId(r.id)||!r.id.startsWith('custom-')||ids.has(r.id)||typeof r.name!=='string'||!r.name.trim()||r.name.length>150||!num(r.servings,100)||r.servings<=0||!num(r.time,1440)||!['breakfast','lunch','dinner','snack'].includes(r.mealType)||!obj(r.items)||!Object.keys(r.items).length||!Object.entries(r.items).every(([id,g])=>validId(id)&&num(g)&&g>0)||!Array.isArray(r.steps)||!r.steps.every(x=>typeof x==='string'&&x.length<=5000)||!Array.isArray(r.gear)||!r.gear.every(x=>typeof x==='string'))throw Error('Invalid recipe');ids.add(r.id);}}
 if(s.foodEntries!==undefined){if(!Array.isArray(s.foodEntries)||s.foodEntries.length>50000)throw Error('Invalid food entries');const ids=new Set;for(const e of s.foodEntries){if(!obj(e)||!validId(e.id)||ids.has(e.id)||!/^\d{4}-\d{2}-\d{2}$/.test(e.day)||!/^([01]\d|2[0-3]):[0-5]\d$/.test(e.time)||typeof e.name!=='string'||!e.name.trim()||e.name.length>150||!['quick','recipe','ingredient'].includes(e.kind)||!num(e.amount)||e.amount<=0||!obj(e.nutrition)||!nutrientKeys.every(k=>num(e.nutrition[k],100000)))throw Error('Invalid food entry');ids.add(e.id);}}
 for(const key of ['hiddenIngredients','foodFavorites'])if(s[key]!==undefined&&(!Array.isArray(s[key])||s[key].some(x=>typeof x!=='string'||x.length>150)))throw Error('Invalid food preferences');
}
